// Direct lookup map for Hindi
export const HINDI_MAP = TRANSLATIONS.hi;

// Lowercase lookup map for case-insensitive matching
export const HINDI_MAP_LOWER = {};
for (const [key, val] of Object.entries(HINDI_MAP)) {
  HINDI_MAP_LOWER[key.toLowerCase()] = val;
}

// Sorted array of English keys by length descending to match longest phrases first
export const PHRASE_KEYS_DESC = Object.keys(HINDI_MAP).sort((a, b) => b.length - a.length);

/**
 * Direct lookup helper with whitespace normalization and case insensitivity
 */
export function translate(text, lang = 'en') {
  if (lang !== 'hi' || !text || typeof text !== 'string') {
    return text;
  }
  const clean = text.replace(/\u00a0/g, ' ').replace(/&amp;/g, '&');
  const trimmed = clean.trim();
  if (!trimmed) return text;

  // Direct match
  if (HINDI_MAP[trimmed]) {
    const match = HINDI_MAP[trimmed];
    const leading = text.match(/^\s*/)[0];
    const trailing = text.match(/\s*$/)[0];
    return leading + match + trailing;
  }

  // Normalized spaces
  const normalized = trimmed.replace(/\s+/g, ' ');
  if (HINDI_MAP[normalized]) {
    const match = HINDI_MAP[normalized];
    const leading = text.match(/^\s*/)[0];
    const trailing = text.match(/\s*$/)[0];
    return leading + match + trailing;
  }

  // Case-insensitive match
  const lower = normalized.toLowerCase();
  if (HINDI_MAP_LOWER[lower]) {
    const match = HINDI_MAP_LOWER[lower];
    const leading = text.match(/^\s*/)[0];
    const trailing = text.match(/\s*$/)[0];
    return leading + match + trailing;
  }

  // Punctuation / bullets check
  const punctPrefixMatch = trimmed.match(/^([·•\-*–—✓✗🔬⚖️ℹ️⚠️✅]+\s*)/);
  if (punctPrefixMatch) {
    const prefix = punctPrefixMatch[1];
    const rest = trimmed.slice(prefix.length).trim();
    if (HINDI_MAP[rest]) {
      const leading = text.match(/^\s*/)[0];
      const trailing = text.match(/\s*$/)[0];
      return leading + prefix + HINDI_MAP[rest] + trailing;
    }
  }

  if (trimmed.endsWith(':')) {
    const rest = trimmed.slice(0, -1).trim();
    if (HINDI_MAP[rest]) {
      const leading = text.match(/^\s*/)[0];
      const trailing = text.match(/\s*$/)[0];
      return leading + HINDI_MAP[rest] + ':' + trailing;
    }
  }

  if (trimmed.startsWith('(') && trimmed.endsWith(')')) {
    const inside = trimmed.slice(1, -1).trim();
    if (HINDI_MAP[inside]) {
      const leading = text.match(/^\s*/)[0];
      const trailing = text.match(/\s*$/)[0];
      return leading + '(' + HINDI_MAP[inside] + ')' + trailing;
    }
  }

  return text;
}
